def categorize_transaction(description, counterparty):
    description = description.lower().strip()
    counterparty = counterparty.lower().strip() if counterparty else ""
    if "stripe" in description or "payouts" in description:
        return "Revenue", "Stripe payouts", 0.95, False
    return "Other", "No clear rule matched", 0.5, True


def process_transaction(row):
    category, rule_matched, rule_used, confidence_score, review_required = categorize_transaction(row['description'], row.get('counterparty', ''))
    return {
        **row,
        'category': category,
        'rule_matched': rule_matched,
        'rule_used': rule_used,
        'confidence_score': confidence_score,
        'review_required': review_required,
    }
